          // Add cardType index; existing records are normalised to "character" on read
          const store = tx.objectStore(STORE);
          if (!store.indexNames.contains("cardType")) {
            store.createIndex("cardType", "cardType");
          }
        }
      },
    });
  }
  return _db;

